# Let's use backtracking with pruning to find a Costas array of order 9
import itertools

def find_costas(n):
    # We'll use backtracking with constraint propagation
    # Represent permutation as list of rows for columns 0..n-1

    # Precompute all possible vectors for quick check
    used_vectors = set()

    def backtrack(col, perm):
        if col == n:
            return perm[:]

        for row in range(n):
            if row in perm:
                continue

            # Check all new vectors with previous columns
            ok = True
            new_vectors = []
            for prev_col in range(col):
                dr = row - perm[prev_col]
                dc = col - prev_col
                if (dr, dc) in used_vectors:
                    ok = False
                    break
                new_vectors.append((dr, dc))

            if not ok:
                continue

            # Add vectors
            for v in new_vectors:
                used_vectors.add(v)
            perm.append(row)

            result = backtrack(col+1, perm)
            if result:
                return result

            # Backtrack
            perm.pop()
            for v in new_vectors:
                used_vectors.remove(v)

        return None

    return backtrack(0, [])

result = find_costas(9)
print("Result:", result)
